select public.admin_notify('📬 Aapki maangi notification — aa gayi', 'Yeh alert aapke admin panel ke bell 🔔 par live hai (panel khula ho to turant dikhta hai). Device push ke liye: panel NAYE tab me kholein, 📲 dabaiye — agar URL bar me chhota bell-icon aaye to use tap karke Allow karein; ya Chrome Notifications settings me "Expand all requests" chun kar 📲 dobara dabaiye. Register hote hi test push phone par KHUD aayegi.', 'owner_request') as sent;
